body.script:
(function () {
  "use strict";
  var csrf = (document.querySelector('meta[name="csrf-token"]') || {}).content || "";
  var projetCourant = null;
  var tagFiltre = null;

  function jjmm(d) {
    if (!d) return "";
    var p = d.slice(0, 10).split("-");
    if (p.length < 3) return d;
    return p[2] + "/" + p[1];
  }

  function etoiles(n) {
    return n > 0 ? "★".repeat(Math.min(n, 3)) : "";
  }

  function get(url) {
    return fetch(url, { credentials: "same-origin" }).then(function (r) {
      return r.json();
    });
  }

  function post(url, data) {
    var fd = new FormData();
    fd.append("csrf_token", csrf);
    Object.keys(data).forEach(function (k) { fd.append(k, data[k]); });
    return fetch(url, { method: "POST", credentials: "same-origin",
      body: fd }).then(function (r) {
      return r.json();
    });
  }

  function chargerProjets() {
    get("/tour/projets/data").then(function (d) {
      if (d.err) { afficherErreur("Projets", d.err); return; }
      var el = document.getElementById("liste-projets");
      if (!d.projets.length) { el.innerHTML = '<div class="vide-projets">Aucun projet.</div>'; return; }
      el.innerHTML = "";
      d.projets.forEach(function (p) {
        var b = document.createElement("button");
        b.type = "button";
        b.className = "projet";
        b.dataset.id = p.id;
        b.innerHTML = '<span class="nom"></span><span class="nb"></span>';
        b.querySelector(".nom").textContent = p.name;
        b.querySelector(".nb").textContent = p.count;
        b.addEventListener("click", function () { ouvrirProjet(p.id); });
        el.appendChild(b);
      });
      document.getElementById("soustitre").textContent =
        d.projets.length + " projet(s)";
      if (!projetCourant) ouvrirProjet(d.projets[0].id);
    }).catch(function () {
      afficherErreur("Projets", "connexion impossible");
    });
  }

  var ETIQ = {
    backlog: ["#94a3b8", "Backlog"],
    afaire: ["#3b82f6", "À faire"],
    encours: ["#f59e0b", "En cours"],
    fait: ["#22c55e", "Fait"],
    test: ["#a855f7", "Test"],
    qa: ["#14b8a6", "QA"]
  };
  var ORDRE = ["backlog", "afaire", "encours", "fait", "test", "qa"];

  function ouvrirProjet(id) {
    projetCourant = id;
    document.querySelectorAll(".projet").forEach(function (b) {
      b.classList.toggle("actif", Number(b.dataset.id) === id);
    });
    var kanban = document.getElementById("kanban");
    kanban.innerHTML = '<div class="chargement">chargement…</div>';
    tagFiltre = null;
    get("/tour/projets/data?projet_id=" + id).then(function (d) {
      if (d.err) { afficherErreur("Kanban", d.err); return; }
      construireFiltres(d.tags || []);
      kanban.innerHTML = "";
      Object.keys(ETIQ).forEach(function (col) {
        var cartes = (d.colonnes || {})[col] || [];
        var div = document.createElement("div");
        div.className = "col";
        div.dataset.col = col;
        div.innerHTML = "<header><span class='dot' style='background:" +
          ETIQ[col][0] + "'></span><b></b><span class='n'></span></header>" +
          "<div class='cartes'></div>";
        div.querySelector("header b").textContent = ETIQ[col][1];
        div.querySelector("header .n").textContent = cartes.length;
        var zone = div.querySelector(".cartes");
        cartes.forEach(function (t) { zone.appendChild(carte(t, col)); });
        div.addEventListener("dragover", function (e) {
          e.preventDefault(); div.classList.add("over");
        });
        div.addEventListener("dragleave", function () {
          div.classList.remove("over");
        });
        div.addEventListener("drop", function (e) {
          e.preventDefault(); div.classList.remove("over");
          var tid = e.dataTransfer.getData("text/plain");
          deplacer(tid, col);
        });
        kanban.appendChild(div);
      });
      filtrer();
    }).catch(function () {
      afficherErreur("Kanban", "connexion impossible");
    });
  }

  function carte(t, col) {
    var d = document.createElement("div");
    d.className = "carte";
    d.draggable = true;
    d.dataset.id = t.id;
    d.dataset.texte = (t.name + " " + (t.user || "") + " " +
      (t.tags || []).join(" ")).toLowerCase();
    d.dataset.tags = JSON.stringify(t.tags || []);
    var meta = "";
    var et = etoiles(t.priority);
    if (et) meta += "<span class='pstar'>" + et + "</span>";
    if (t.user) meta += "<span class='badge'>" + echapper(t.user) + "</span>";
    if (t.deadline) meta += "<span class='badge echeance'>" + jjmm(t.deadline) + "</span>";
    t.tags.forEach(function (g) {
      meta += "<span class='badge'>" + echapper(g) + "</span>";
    });
    d.innerHTML = "<div class='titre'></div>" +
      (meta ? "<div class='meta'>" + meta + "</div>" : "");
    d.querySelector(".titre").textContent = t.name;
    var i = ORDRE.indexOf(col);
    var gauche = i > 0 ? ORDRE[i - 1] : null;
    var droite = i >= 0 && i < ORDRE.length - 1 ? ORDRE[i + 1] : null;
    if (gauche || droite) {
      var nav = document.createElement("div");
      nav.className = "deplacer";
      if (gauche) {
        var b1 = document.createElement("button");
        b1.type = "button"; b1.textContent = "◀";
        b1.title = "Déplacer vers " + ETIQ[gauche][1];
        b1.dataset.col = gauche;
        nav.appendChild(b1);
      }
      if (droite) {
        var b2 = document.createElement("button");
        b2.type = "button"; b2.textContent = "▶";
        b2.title = "Déplacer vers " + ETIQ[droite][1];
        b2.dataset.col = droite;
        nav.appendChild(b2);
      }
      nav.addEventListener("click", function (e) {
        e.stopPropagation();
        var btn = e.target.closest("button");
        if (btn && btn.dataset.col) deplacer(t.id, btn.dataset.col);
      });
      d.appendChild(nav);
    }
    d.addEventListener("dragstart", function (e) {
      e.dataTransfer.setData("text/plain", String(t.id));
      d.classList.add("tirant");
    });
    d.addEventListener("dragend", function () { d.classList.remove("tirant"); });
    d.addEventListener("click", function () { ouvrirDetail(t.id); });
    return d;
  }

  function construireFiltres(tags) {
    var cont = document.getElementById("filtres-tags");
    cont.innerHTML = "";
    if (!tags.length) return;
    tags.forEach(function (g) {
      var b = document.createElement("button");
      b.type = "button";
      b.className = "tag-filtre";
      b.dataset.tag = g.name;
      b.innerHTML = '<span class="n"></span><span class="c"></span>';
      b.querySelector(".n").textContent = g.name;
      b.querySelector(".c").textContent = g.count;
      b.addEventListener("click", function () {
        tagFiltre = (tagFiltre === g.name) ? null : g.name;
        document.querySelectorAll(".tag-filtre").forEach(function (x) {
          x.classList.toggle("actif", x.dataset.tag === tagFiltre);
        });
        filtrer();
      });
      cont.appendChild(b);
    });
  }

  function filtrer() {
    var q = (document.getElementById("recherche").value || "").trim().toLowerCase();
    document.querySelectorAll(".carte").forEach(function (c) {
      var tagsCarte = [];
      try { tagsCarte = JSON.parse(c.dataset.tags || "[]") || []; }
      catch (e) { tagsCarte = []; }
      var dansTag = !tagFiltre || tagsCarte.indexOf(tagFiltre) >= 0;
      var ok = (!q || (c.dataset.texte || "").indexOf(q) >= 0) && dansTag;
      c.style.display = ok ? "" : "none";
    });
    document.querySelectorAll(".col").forEach(function (col) {
      var visibles = 0;
      col.querySelectorAll(".carte").forEach(function (c) {
        if (c.style.display !== "none") visibles++;
      });
      col.querySelector("header .n").textContent = visibles;
    });
  }

  var inputRecherche = document.getElementById("recherche");
  if (inputRecherche) inputRecherche.addEventListener("input", filtrer);

  function echapper(s) {
    return String(s).replace(/[&<>"']/g, function (c) {
      return "&#" + c.charCodeAt(0) + ";";
    });
  }

  function deplacer(tid, colonne) {
    post("/tour/projets/deplacer", { task_id: tid, colonne: colonne })
      .then(function (r) {
        if (r.ok) {
          document.getElementById("detail").classList.remove("ouvert");
          ouvrirProjet(projetCourant);
        }
        else { alert(r.err || "déplacement impossible"); }
      });
  }

  function ouvrirDetail(id) {
    get("/tour/projets/detail/" + id).then(function (d) {
      if (d.err) { alert(d.err); return; }
      var el = document.getElementById("detail");
      el.innerHTML = "";
      var fermer = document.createElement("button");
      fermer.className = "fermer"; fermer.textContent = "✕";
      fermer.addEventListener("click", function () {
        el.classList.remove("ouvert");
      });
      var h = document.createElement("h3"); h.textContent = d.name;
      var p = document.createElement("div"); p.className = "proj";
      p.textContent = d.project + (d.stage ? " · " + d.stage : "");
      el.appendChild(fermer); el.appendChild(h); el.appendChild(p);
      if (d.description) {
        var de = document.createElement("div"); de.className = "desc";
        de.textContent = d.description; el.appendChild(de);
      }
      var ch = document.createElement("div"); ch.className = "champs";
      ch.innerHTML =
        "<div class='ligne'><b>Priorité</b><span>" + (etoiles(d.priority) || "normale") + "</span></div>" +
        "<div class='ligne'><b>Assigné</b><span>" + (d.user ? echapper(d.user) : "—") + "</span></div>" +
        "<div class='ligne'><b>Échéance</b><span>" + (d.deadline ? jjmm(d.deadline) : "—") + "</span></div>" +
        "<div class='ligne'><b>Étiquettes</b><span>" + (d.tags.length ? d.tags.map(echapper).join(", ") : "—") + "</span></div>" +
        "<div class='ligne'><b>Colonne</b><span><select id='colonne-sel'>" +
        ORDRE.map(function (c) {
          return "<option value='" + c + "'" + (d.colonne === c ? " selected" : "") +
            ">" + ETIQ[c][1] + "</option>";
        }).join("") + "</select></span></div>" +
        "<div class='ligne'><b>Créée</b><span>" + d.create.slice(0, 10) + "</span></div>" +
        "<div class='ligne'><b>Modifiée</b><span>" + d.write.slice(0, 10) + "</span></div>";
      el.appendChild(ch);
      var selCol = el.querySelector("#colonne-sel");
      if (selCol) {
        selCol.addEventListener("change", function () {
          deplacer(d.id, selCol.value);
        });
      }
      var liens = document.createElement("div"); liens.className = "liens";
      var a = document.createElement("a"); a.className = "btn";
      a.href = d.odoo; a.textContent = "Ouvrir dans Odoo";
      var b = document.createElement("button"); b.className = "btn fantome";
      b.textContent = "Fermer";
      b.addEventListener("click", function () { el.classList.remove("ouvert"); });
      liens.appendChild(a); liens.appendChild(b);
      el.appendChild(liens);
      el.classList.add("ouvert");
    }).catch(function () { alert("détail impossible"); });
  }

  function afficherErreur(cible, msg) {
    var el = cible === "Projets" ? document.getElementById("liste-projets")
      : document.getElementById("kanban");
    el.innerHTML = '<div class="erreur">' + echapper(msg) + "</div>";
  }

  chargerProjets();
})();
